#include <charconv>
#include <iostream>
#include <optional>
#include <string_view>

std::optional<int> parse_int(std::string_view s) {
    int value{};
    auto [ptr, ec] = std::from_chars(s.data(), s.data() + s.size(), value);
    if (ec != std::errc{} || ptr != s.data() + s.size()) return std::nullopt;
    return value;
}

enum class Choice { Add, Remove, Quit };

void run(Choice c) {
    switch (c) {                         // no default: -Wswitch checks coverage.
    case Choice::Add:    std::cout << "add\n";    break;
    case Choice::Remove: std::cout << "remove\n"; break;
    case Choice::Quit:   std::cout << "bye\n";    break;
    }
}

int main() {
    if (auto n = parse_int("42"); n) {   // n scoped to this if/else.
        std::cout << "got " << *n << '\n';
    } else {
        std::cout << "not a number\n";
    }
    run(Choice::Add);
}
